#!/usr/bin/env python3
"""Build the additive, privacy-safe static decision-readiness dashboard."""
import html, json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
D = ROOT / 'data'
sources = {x['id']:x for x in json.loads((D/'sources.json').read_text())}
context = json.loads((D/'verified_context.json').read_text())
questions = json.loads((D/'questions.json').read_text())
risks = json.loads((D/'risks.json').read_text())
def esc(x): return html.escape(str(x))
def link(sid, label=None):
    s=sources[sid]
    return f'<a href="{esc(s["url"])}" target="_blank" rel="noopener noreferrer">{esc(label or s["id"]+" ↗")}</a>'
def links(ids): return ' · '.join(link(i) for i in ids)
nav=[('index.html','Overview'),('market.html','Area & economy'),('questions.html','Questions'),('options.html','Decision paths'),('risks.html','Risk register'),('flagged.html','Flagged for review'),('sources.html','Sources & method'),('privacy.html','Privacy'),('verification.html','Verification')]
def shell(title, body, active):
    items=''.join(f'<a href="{u}"'+(' aria-current="page"' if u==active else '')+f'>{n}</a>' for u,n in nav)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)} · Decision review</title><meta name="description" content="Privacy-first evidence and decision review for an anonymized single-tenant NNN property scenario."><link rel="stylesheet" href="assets/style.css"><meta name="robots" content="index,follow"></head><body><a class="skip" href="#main">Skip to content</a><header><div class="wrap top"><a class="brand" href="index.html"><span class="mark">J</span><span>Property decision review<small>Jack in the Box · NNN · Central Los Angeles (area description only)</small></span></a><nav aria-label="Main navigation">{items}</nav></div></header><main id="main" class="wrap">{body}</main><footer><div class="wrap"><p><strong>Evidence-first, anonymized decision support.</strong> No property-specific appraisal, legal opinion, tax advice, or investment advice. Personal and parcel-identifying information is intentionally excluded. <a href="privacy.html">Privacy safeguards</a> · <a href="verification.html">Verification log</a></p><p>Evidence accessed 2026-11-12. Values are published only with official source links; unknown property-specific values remain unknown.</p></div></footer></body></html>'''
# Overview
body='''<section class="hero"><p class="eyebrow">Executive summary · decision readiness</p><h1>Keep the options open. Do not decide “sell vs. renew” from the information currently available.</h1><p class="lead">The known facts are only an anonymized Jack in the Box NNN property described as “around central Los Angeles” and a lease expiry window of 2030–2035. The site address, exact expiration, rent, options, NOI, debt, basis, hazards, insurance, and owner objectives are not provided. Therefore, a property-specific valuation or defensible final sale/renewal recommendation cannot be made without inventing inputs.</p><div class="callout"><b>Best current course of action</b><p>Run a private, time-boxed dual track: (1) have counsel abstract the lease and calendar every notice deadline; (2) obtain independent valuation, insurance/hazard, condition, and tenant-credit diligence; (3) request a nonbinding extension proposal with documented rent reset/credit support while obtaining a sale opinion; (4) compare after-tax risk-adjusted proceeds only after the facts are known. Do not grant an extension, waive an option, list, or sign a sale/exchange solely on this public-area analysis.</p></div><div class="kpis"><div><b>0</b><span>property-specific financial inputs verified</span></div><div><b>6</b><span>current official context observations — all broad-area only</span></div><div><b>20</b><span>critical questions and evidence requests</span></div><div><b>15</b><span>risk events mapped across choices</span></div></div></section>
<h2>What is known — and what it does not prove</h2><div class="tablewrap"><table><thead><tr><th>Known from official public source</th><th>Value and period</th><th>Scope / decision limitation</th><th>Source</th></tr></thead><tbody>'''
for r in context:
    body+=f'<tr><td>{esc(r["topic"])}</td><td><b>{esc(r["value"])}</b><br>{esc(r["period"])}</td><td>{esc(r["geography"])}. {esc(r["meaning"])}</td><td>{link(r["source"])}</td></tr>'
body+='''</tbody></table></div><p class="note">Official regional statistics establish context, not a property forecast. They do not establish foot traffic, catchment income, franchisee credit, rent growth, cap rate, or sale price for this site.</p><h2>Decision sequence</h2><div class="cards"><article><span class="tag">01 · Protect</span><h3>Preserve legal and insurance options</h3><p>Abstract the executed lease, verify exact term/notice dates, request current coverage and written renewal terms. Keep identifying documents private.</p></article><article><span class="tag">02 · Measure</span><h3>Get independent facts</h3><p>Establish actual NOI and tenant credit, then appraise as-is and under documented extension/vacancy cases. Screen parcel hazards and alternative-use constraints.</p></article><article><span class="tag">03 · Compare</span><h3>Use owner-level, after-tax scenarios</h3><p>Compare sell, extend, hold/renew, hold/vacate, and delayed-sale cases after transaction/tax costs, debt payoff, insurance and replacement investment risk.</p></article><article><span class="tag">04 · Decide</span><h3>Choose only when triggers are met</h3><p>Use the decision gates on the path page. Record who verified each input, the source, date, uncertainty and reversal trigger.</p></article></div><h2>Dashboard</h2><div class="cards"><a class="tile" href="market.html"><b>Area & economy</b><span>Verified broad context; required local factors and official data pathway.</span></a><a class="tile" href="questions.html"><b>Questions</b><span>20 decision-critical questions, what is known, and how to obtain missing facts.</span></a><a class="tile" href="options.html"><b>Decision paths</b><span>Sell, extend, renew, hold, or re-tenant: conditional comparison and decision gates.</span></a><a class="tile" href="risks.html"><b>Risk register</b><span>Business-as-usual and black-swan risks with mitigations across choices.</span></a><a class="tile" href="flagged.html"><b>Flagged for review</b><span>Material assumptions and evidence gaps in prior analysis that could mislead if read as verified.</span></a><a class="tile" href="privacy.html"><b>Privacy</b><span>What this site excludes and how to complete private diligence safely.</span></a></div><div class="callout warning"><b>Scope warning</b><p>“Around central Los Angeles” does not establish City of Los Angeles jurisdiction. This matters for zoning, taxes, school boundaries and hazards. Do not apply city-specific rules until exact jurisdiction is privately verified.</p></div>'''
(ROOT/'index.html').write_text(shell('Executive summary and overview',body,'index.html'))
# market
body='''<section class="pagehead"><p class="eyebrow">Area & economy</p><h1>Broad indicators are available; the property's local trade area is not identified.</h1><p class="lead">Central Los Angeles is not a usable parcel-level geography. We present only facts actually confirmed in official sources and explain the exact next lookup needed for each economic factor.</p></section><h2>Current official economic context</h2><div class="tablewrap"><table><thead><tr><th>Measure</th><th>Observed value</th><th>Geography / period</th><th>Interpretation limit</th><th>Source</th></tr></thead><tbody>'''
for r in context:
    body+=f'<tr><td>{esc(r["topic"])}</td><td><b>{esc(r["value"])}</b></td><td>{esc(r["geography"])}<br>{esc(r["period"])}</td><td>{esc(r["meaning"])}</td><td>{link(r["source"])}</td></tr>'
body+='''</tbody></table></div><p class="note">BLS’s November 4, 2026 summary is a cross-section of labor, price and other data with different geographies and revisions. BEA’s 2024 county aggregate is not neighborhood-level per-capita income. No growth rate from these figures is mechanically projected to 2030–2035.</p><h2>Required local factors — no site-level values assigned</h2><div class="tablewrap"><table><thead><tr><th>Factor</th><th>Status</th><th>What to retrieve (after private location verification)</th><th>Official source</th></tr></thead><tbody>'''
items=[('Population, age, household size','Not assigned','ACS tract/block-group estimates and margins of error; show 5-year change and boundary/vintage.','S01'),('Household income, poverty, tenure, housing costs','Not assigned','ACS income distribution and housing indicators; use margins of error; do not substitute county aggregate.','S01'),('Employment, unemployment, industry and commute shed','Partially observed at metro only','BLS metro/county series; local worker/commute geography where available; separate job base from store customer demand.','S02'),('County output and income','Verified county-level only','BEA county GDP/income series and revisions; identify reference year and do not present as catchment income.','S03'),('Schools / educational systems','Not assigned','CDE DataQuest school/district results only after attendance/district boundary is verified; educational outcomes are contextual, not causal site-demand proxies.','S04'),('Zoning, development, access and land use','Not assigned','Check parcel and nearby planned projects in correct city/county planning systems; ZIMAS only if City of LA jurisdiction is confirmed.','S05'),('Wildfire, flood, seismic, liquefaction, landslide','Not assigned','Parcel screening against official map layers, then engineering and insurance review; map screen is not a risk probability.','S07'),('Consumer prices / cost of living','Metro CPI observed','Use BLS trend as price context only; rent escalators and asset prices are separate contractual/market variables.','S02')]
for name,status,need,sid in items: body+=f'<tr><td>{esc(name)}</td><td>{esc(status)}</td><td>{esc(need)}</td><td>{link(sid)}</td></tr>'
body+='''</tbody></table></div><h2>Projection method that can be reliable without pretending to know the answer</h2><ol class="steps"><li><b>Define geography privately.</b> Use address/APN to identify correct municipal boundaries, census tract/block group, site access and a defensible drive-time or trade-area definition; do not publish the coordinate.</li><li><b>Collect a consistent time series.</b> Record each official source's native geography, release date, vintage, estimate/error range and revision status. Use ACS margins of error and avoid mixing incompatible boundary years.</li><li><b>Model causal channels, not just population growth.</b> Tie local household/demographic indicators to store-level tenant sales (if contractually available), employment/commute, competition, access, zoning, rent and tenant credit. Keep correlation/context separate from causal evidence.</li><li><b>Run paths and stress cases.</b> Model contract rent, renewal rent/likelihood (unknown until supported), vacancy, landlord costs, cap rates, insurance, tax/transaction cost, debt and owner tax. Add joint shocks (recession plus insurance shock; earthquake plus downtime), not only independent hazard assumptions.</li><li><b>Update and back-test.</b> Re-estimate at each material release and annual lease milestone; compare prior projected values to observed actual outcomes. No validated probability model can be calibrated from the facts currently supplied.</li></ol><div class="callout"><b>Projection status: not yet computable.</b><p>There is not enough property-specific input for a numeric sell-versus-renew projection. Publishing a point estimate, probability-weighted rank, or Monte Carlo “chance of winning” now would create false precision. Keep value fields blank until supported by actual lease cash flows, independent valuation and private tax/owner inputs.</p></div>'''
(ROOT/'market.html').write_text(shell('Area and economy',body,'market.html'))
# questions
body='''<section class="pagehead"><p class="eyebrow">Pre-decision checklist</p><h1>Questions, current answers, and how to close each gap</h1><p class="lead">“Unknown” is intentional. Public regional data cannot answer private lease, parcel, tenant-credit, debt, tax-basis, insurance, or owner-objective questions. Every item has an official source link for context or the applicable public-data route.</p></section><div class="tablewrap"><table><thead><tr><th>ID / area</th><th>Question</th><th>Known answer</th><th>Missing evidence & method</th><th>Priority</th><th>Official source</th></tr></thead><tbody>'''
for q in questions:
    body+=f'<tr><td><b>{esc(q["id"])}</b><br>{esc(q["area"])}</td><td>{esc(q["question"])}</td><td>{esc(q["answer"])}</td><td><b>Needed:</b> {esc(q["needed"])}<br><b>Method:</b> {esc(q["method"])}</td><td><span class="priority {q["priority"].lower()}">{esc(q["priority"])}</span></td><td>{links(q["sources"])}</td></tr>'
body+='</tbody></table></div><p class="note">For private records, use a lawyer, CPA, broker, insurer, appraiser, or fiduciary through confidential channels. This public repository should contain only redacted conclusions, never originals or identifying details.</p>'
(ROOT/'questions.html').write_text(shell('Questions and missing information',body,'questions.html'))
# options
body='''<section class="pagehead"><p class="eyebrow">Decision pathways</p><h1>No path dominates without the missing facts.</h1><p class="lead">The recommended immediate decision is to preserve optionality while gathering evidence—not a final sell/renew choice. Compare net present value, after-tax cash flow, liquidity, downside and concentration using the same horizon and risk tolerance.</p></section><div class="tablewrap"><table><thead><tr><th>Path</th><th>Potential benefit</th><th>Principal risks / cost</th><th>Evidence gate before action</th><th>Review position</th><th>Official source</th></tr></thead><tbody>'''
paths=[('Sell before expiry','Liquidity; can reduce single-tenant/parcel concentration; may realize value before term shortens.','Sale cost, tax, debt payoff, timing and price risk; sale proceeds create replacement/investment risk. 1031 deferral is conditional, not automatic tax elimination.','Independent as-is valuation and comparable sales; actual rent/term/NOI; debt payoff; tax-basis analysis; replacement portfolio and transaction cost.','Do not recommend now. Consider if credible net after-tax proceeds meet owner goals and price compensates for giving up rent/options.','S11'),('Negotiate extension then sell','Could improve term certainty or lease cash flow before sale; preserves a sale option if tenant agrees.','Tenant may refuse; extension may lock low rent, give away value, lengthen concentration, or add negotiation/legal cost. Longer term is not guaranteed to increase value.','Executed lease and notice dates; independent market-rent support; tenant/guarantor credit; enforceable extension; fresh appraisal with executed terms.','Worth exploring as a nonbinding parallel discussion only; no assertion that this is highest-value strategy.','S10'),('Renew / extend and hold','Retains contractual income; can avoid immediate sale transaction/tax; maintains ownership exposure.','Tenant concentration; rent may be below market; insurance/repair/tax risk; capital remains illiquid; extension options may have deadlines.','Written renewal terms; rent and actual expense history; credit/guaranty; full hazard/insurance/condition review; owner after-tax cash flow.','Consider only if risk-adjusted after-tax value beats alternatives and owner can manage concentration.','S06'),('Hold to expiry, then re-tenant or sell','Keeps option to collect near-term contract rent and decide later with new information.','Shorter term may reduce buyer pool; tenant departure can cause vacancy, leasing capital and lower NOI; market could deteriorate before expiry.','Lease notice calendar; alternative-use/zoning; written broker leasing study; vacancy stress; condition and expense obligations.','Do not “wait and see” passively; preserve notice rights and prepare a re-tenant plan.','S05'),('Sell after lease expiry / vacancy','Potential flexibility to sell vacant or reposition depending on land/use demand.','Vacancy removes contractual income and buyer financing appeal; costs, downtime, environmental/entitlement and demolition risk.','Current local land-use rules, site condition, tenant surrender status, validated vacant-land/reuse values, carrying-cost capacity.','Model separately; do not assume vacant land is more valuable.','S05')]
for n,b,r,g,p,sid in paths: body+=f'<tr><td><b>{esc(n)}</b></td><td>{esc(b)}</td><td>{esc(r)}</td><td>{esc(g)}</td><td>{esc(p)}</td><td>{link(sid)}</td></tr>'
body+=f'''</tbody></table></div><h2>Decision gates (evidence-based, not arbitrary cutoffs)</h2><div class="tablewrap"><table><thead><tr><th>If verified evidence shows…</th><th>Then the reasonable next step is…</th><th>Source / rule context</th></tr></thead><tbody><tr><td>A legal notice deadline or option right is approaching</td><td>Have counsel calendar and preserve the right first; valuation work should not cause a missed notice.</td><td>Read and enforce the private executed lease; brand-level SEC disclosure is not the actual contract. {link('S10')}</td></tr><tr><td>Renewal terms are written, creditworthy and independently valued; hold cash flows exceed sale alternatives under a conservative stress</td><td>Consider extension/hold only if owner risk limits and concentration tolerance also permit.</td><td>Property taxes and transfer consequences depend on actual parcel/transaction circumstances. {links(['S06','S12','S13'])}</td></tr><tr><td>Net sale proceeds after debt, taxes, costs, and realistic replacement risk exceed risk-adjusted hold value</td><td>Consider sale; have tax counsel test taxable sale and any qualifying exchange before signing.</td><td>IRS Form 8824 instructions explain reporting and statutory framework; no individual eligibility determination. {link('S11')}</td></tr><tr><td>Parcel hazard exposure, insurance exclusion/cost, or major repairs materially change expected loss</td><td>Re-run downside cases and renegotiate, sell, or insure based on quantified residual risk; no blanket “sell” trigger without price/tax facts.</td><td>Official maps screen hazards but do not substitute for engineering or underwriting. {links(['S07','S08','S09'])}</td></tr><tr><td>Any essential number remains an unsupported proxy</td><td>Do not turn it into a point estimate. Leave blank, document the gap, and obtain the primary record.</td><td>See the flagged review page and verification protocol. {link('S01')}</td></tr></tbody></table></div><div class="callout"><b>Personal wealth balance</b><p>Asset-level return is not the same as owner-level suitability. A final choice should compare after-tax spendable cash, income reliability, liquidity, diversification, estate/tax constraints, leverage and ability to absorb correlated shocks. Personal balance-sheet and health information must stay private and is not required on this site.</p></div>'''
(ROOT/'options.html').write_text(shell('Decision paths',body,'options.html'))
# risks
body='''<section class="pagehead"><p class="eyebrow">Risk register</p><h1>Business-as-usual and rare shocks can combine.</h1><p class="lead">Likelihoods and loss sizes are intentionally not invented. Score them only after parcel, lease, insurance and financial diligence. Natural hazard maps identify screening areas; they do not quantify a property's annual loss probability.</p></section><div class="tablewrap"><table><thead><tr><th>Event</th><th>Class</th><th>Sell</th><th>Extend</th><th>Hold / re-tenant</th><th>Mitigation</th><th>Official source</th></tr></thead><tbody>'''
for r in risks: body+=f'<tr><td><b>{esc(r["event"])}</b></td><td>{esc(r["class"])}</td><td>{esc(r["sell"])}</td><td>{esc(r["extend"])}</td><td>{esc(r["hold"])}</td><td>{esc(r["mitigation"])}</td><td>{link(r["source"])}</td></tr>'
body+='</tbody></table></div><h2>Correlated stress scenarios to model after diligence</h2><ul class="bullets"><li><b>Earthquake + insurance stress:</b> damage or access disruption, a large deductible/exclusion, regional repair-cost spike, tenant interruption and lower buyer liquidity.</li><li><b>Wildfire smoke/evacuation + recession:</b> store interruption and insurance changes arrive with weaker local household spending and lower sale prices.</li><li><b>Tenant closure + high rates:</b> rent stops as cap rates expand and re-tenanting finance/tenant improvements become more costly.</li><li><b>Flood/access disruption + claim denial:</b> physical damage and business interruption exceed mapped assumptions or applicable coverage.</li><li><b>Exchange failure + market fall:</b> a missed statutory timeline or poor replacement purchase leaves tax liability and reinvestment losses; model taxable sale too.</li></ul><p class="note">No “black swan probability” is assigned. Before using risk scores, define exposure, vulnerability, consequence, insurance recovery, recovery time, and source vintage for the actual parcel.</p>'
(ROOT/'risks.html').write_text(shell('Risk register',body,'risks.html'))
# flagged
flags=[
('F01','Proxy rent shown in prior model','Root model input A1 is $150,000/year, calculated as 8% of Jack in the Box FY2025 average unit volume. The model itself labels it a placeholder, not subject rent. Any sale value or wealth comparison derived from it is not an appraisal or property estimate.','Replace only with actual executed lease rent/NOI and reconciled expenses; keep prior output labelled illustrative.','S10'),
('F02','Expiry date replaced by midpoint','Root model selects 2032 as a midpoint of stated 2030–2035, although the executed expiry/options are unavailable. Timing changes rent duration, option deadlines, terminal value and buyer pricing.','Use the executed lease and notice evidence; model each actual option/date, not a midpoint.','S10'),
('F03','Exit cap and renewal assumptions are analyst inputs','Prior projection code uses scenario cap rates, rent escalators, tenant renewal probabilities and renewal rent factors. These are not official published measurements of this unidentified site; model risk scores also self-identify as analyst judgments.','Obtain subject-specific appraisals, lease and tenant evidence; show assumptions as ranges and avoid presenting scenario outputs as forecast probabilities.','S10'),
('F04','7.3% REIT yield is not a subject-property reinvestment quote','A public REIT’s acquisition yield (if cited) reflects its acquisitions and portfolio, not a guaranteed yield available to this owner or an equivalent replacement property.','Get actual replacement-property proposals and compare net, after-tax, fee-adjusted, leverage-adjusted returns; retain taxable-sale alternative.','S11'),
('F05','Metro/county averages are not the property trade area','BLS/BEA statistics aggregate large geographies. Without the privately held location there is no way to select correct tract, school district, drive-time catchment, zoning jurisdiction or parcel hazard overlay.','Geocode privately; disclose native geographic level and uncertainty; never print location or personal identifiers.','S01'),
('F06','City-specific tax eligibility is unconfirmed','Central LA does not prove the parcel is in Los Angeles City. City transfer tax/Measure ULA applicability and city planning maps depend on jurisdiction; rules may change before a sale.','Verify municipality and current official transfer tax rules at closing; do not apply a City rate based only on the area label.','S13'),
('F07','Brand public filing does not answer franchisee/property questions','SEC company disclosures describe the issuer/system, not necessarily the private franchisee operating this unidentified unit, its guarantor, unit sales, lease or renewal choice.','Obtain private tenant/guarantor financials and site-specific operating data under appropriate confidentiality controls.','S10'),
('F08','No parcel-level hazard result is possible here','No location is supplied; wildfire, flood, earthquake/liquefaction and insurance claims cannot be assigned based on metropolitan geography. A map check alone also does not equal engineering or insurance review.','Perform private parcel screens at FEMA, CAL FIRE/local, and CGS; obtain engineer/broker review and confirm policy terms.','S07'),
('F09','No tax/after-tax decision can be calculated','Basis, depreciation, debt, ownership structure, tax status, exchange eligibility and replacement property are private and absent. Tax deferral is not the same as tax elimination.','CPA/tax counsel uses confidential records and current IRS rules; publish only an anonymized conclusion if needed.','S11')]
body='''<section class="pagehead"><p class="eyebrow">Flagged for review</p><h1>Material gaps and model limitations</h1><p class="lead">These flags do not prevent using this site as a checklist. They do prevent treating prior precision or rankings as verified property advice.</p></section><div class="tablewrap"><table><thead><tr><th>ID / issue</th><th>Finding and why it matters</th><th>Required correction / review</th><th>Official source</th></tr></thead><tbody>'''
for id,n,f,c,sid in flags: body+=f'<tr><td><b>{id}</b><br>{esc(n)}</td><td>{esc(f)}</td><td>{esc(c)}</td><td>{link(sid)}</td></tr>'
body+='</tbody></table></div><h2>Repository audit notes</h2><p>Root files are retained as prior workbooks. The root generator/model and check suite were run on 2026-11-12; see <a href="verification.html">verification log</a>. Generated values in the root workbook are not newly adopted as current verified facts by this additive dashboard. This review deliberately does not alter those other sessions’ files.</p><p>Review references: <a href="../tools/model.py">root model source</a>, <a href="../data/valuation.json">root valuation inputs</a>, <a href="../executive-summary.html">root executive summary</a>. Links are repository evidence, not official data sources.</p>'
(ROOT/'flagged.html').write_text(shell('Flagged for review',body,'flagged.html'))
# sources
body='''<section class="pagehead"><p class="eyebrow">Sources & verification method</p><h1>Official sources used; scope limits are explicit.</h1><p class="lead">Each observation and question links to an official primary source. We fetched/read the source pages on 2026-11-12; the evidence table preserves the source's level, period and limitation. External sites may change.</p></section><div class="tablewrap"><table><thead><tr><th>ID</th><th>Official publisher/source</th><th>Use and limitation</th><th>Checked</th></tr></thead><tbody>'''
for s in sources.values(): body+=f'<tr><td><b>{esc(s["id"])}</b></td><td><a href="{esc(s["url"])}" target="_blank" rel="noopener noreferrer">{esc(s["name"])} ↗</a></td><td>{esc(s["scope"])}</td><td>{esc(s["checked"])}</td></tr>'
body+='''</tbody></table></div><h2>Verification rules</h2><ul class="bullets"><li>Only primary official sources are used for factual observations: government statistical offices, regulators, official tax agencies, or SEC EDGAR.</li><li>A link is not proof that a site-specific value was established. The source's geographic and subject scope is stated beside every observation.</li><li>Unknown property-specific values are not filled by regional averages, analyst assumptions, brand averages or midpoint estimates.</li><li>Every data row in this workspace contains at least one official source link. Source files contain IDs, direct URL, scope and access date.</li><li>Private documents and owner details belong in confidential diligence—not this public repository.</li></ul><p>For methods, see <a href="market.html">projection framework</a>; for required inputs, see <a href="questions.html">questions checklist</a>.</p>'''
(ROOT/'sources.html').write_text(shell('Official sources and method',body,'sources.html'))
# privacy
body=f'''<section class="pagehead"><p class="eyebrow">Privacy · highest priority</p><h1>No personal or parcel-identifying information is published here.</h1><p class="lead">Privacy protection takes precedence over making a parcel-level analysis look complete. Exact location is not needed to provide this public decision framework and is not requested here.</p></section><div class="callout"><b>Public-site rule</b><p>Do not add personal names, home/business street address, APN, legal description, account/loan identifiers, tenant employee/contact details, private financial statements, or unredacted documents to site files, issues, chat, or commits. Use generic placeholders only. Store source documents with your attorney/adviser or in an owner-controlled private system, not GitHub Pages.</p></div><h2>Safe private workflow</h2><ol class="steps"><li>Keep unredacted lease, title, tax, debt, financial, insurer and tenant-credit files off the public repo.</li><li>Give each adviser only the documents needed under confidentiality controls. Have counsel abstract the lease without exposing personal details on public pages.</li><li>For official parcel/hazard lookups, an owner/adviser can privately use the exact location on the official portals linked here. Publish only non-identifying result categories if necessary, with source, date, and caveat.</li><li>Before any public commit, scan generated pages, assets, JSON, logs, branch/PR text and filenames. Remove identifiers rather than hashing them; a hash can still enable linkage.</li><li>Ask legal/tax counsel before sharing tenant or financial information. Public-company disclosures are not a reason to publish private franchisee records.</li></ol><h2>What is intentionally absent</h2><div class="tablewrap"><table><thead><tr><th>Data class</th><th>Published value</th><th>Why absent</th><th>Official context link</th></tr></thead><tbody><tr><td>Owner identity or personal financial/health details</td><td>None</td><td>Not required for public research; personal suitability can be analyzed privately and anonymously.</td><td>{link('S11')}</td></tr><tr><td>Exact address, APN, legal description or parcel geometry</td><td>None</td><td>Property identity is withheld; no parcel-level hazard, zoning, school or census claim is made.</td><td>{links(['S05','S06'])}</td></tr><tr><td>Lease, rent, debt, adjusted basis, tenant/guarantor records</td><td>None</td><td>Confidential owner/tenant documents are not in public sources or this repository.</td><td>{links(['S10','S11'])}</td></tr></tbody></table></div><p class="note">This repository may be publicly viewable and searchable. Do not assume an anonymized document remains anonymous if it includes dates, parcel details or unique financial terms.</p>'''
